import{z as s,x as n,o as r,c as d,q as A,j as o,D as t,d as e,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Percolator 与 TiDB 案例","description":"","frontmatter":{"title":"Percolator 与 TiDB 案例","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dt-percolator-tidb.md","filePath":"cs/dt-percolator-tidb.md","lastUpdated":1791413859000}'),c={name:"cs/dt-percolator-tidb.md"};function C(P,E,D,p,T,m){const B=n("Mermaid");return r(),d("div",null,[E[2]||(E[2]=A('<h1 id="percolator-与-tidb-案例" tabindex="-1">Percolator 与 TiDB 案例 <a class="header-anchor" href="#percolator-与-tidb-案例" aria-label="Permalink to &quot;Percolator 与 TiDB 案例&quot;">​</a></h1><div class="epigraph"><p>把 2PC 的状态机塞进数据表，协调者的崩溃就从一个进程故障，变成一行残留锁的清理问题。</p><footer>—— 据 Peng and Dabek, Large-scale Incremental Processing Using Distributed Transactions and Notifications, OSDI 2010；TiKV 事务模型文档整理</footer></div><p><a href="/cs/dt-2pc-implementation">上一课</a>把 2PC 的账钉在日志序与不确定窗口上。本课看两份把这套账搬进 KV 的实现：主干课的 <a href="/cs/percolator">Percolator</a> 给过 lock/write/data 三列的外观，本课补两处它没展开的细节——提交点为什么必须落在主锁上、崩溃后谁有权收拾——再看 TiDB 怎么把这套为增量处理设计的协议改造成 OLTP 引擎的底座。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Percolator 没有独立协调者进程：2PC 的状态就是表里的行。客户端缓冲写集，提交时选一个键作主锁，其余键的次锁都指向它。缺口有二。其一是<strong>崩溃后的判定权</strong>：读者在快照时间之后看到一把残锁，要顺次锁指针查主锁——主锁行已变成 write 记录则前滚（替它补完清理），主锁不在则回滚（删掉残锁）。这个判定不依赖任何进程活着，是「状态在数据里」换来的性质。其二是<strong>延迟</strong>：每次读要查 lock 列，每次提交要多次 KV RPC 加两次取戳；主干课说过它只配增量作业。TiDB 要拿它当 OLTP 底座，账必须重算。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TiKV 承袭 Percolator 的账，改动都在税目上。取戳：PD 充当 TSO 全局发号，客户端一次批量预取一段号，用本地递增消化单个事务的两次取戳，把发号 RPC 从每次提交里摊薄出去。读：在 startTS 下检查键上有没有 \\(ts \\lt \\mathrm{startTS}\\) 仍未清的锁——有则退避重试或主动 resolve。写路径有两种脾气：乐观模式沿 Percolator 原样，提交才见冲突、冲突即整单重试；悲观模式（TiDB 后来加入并把 OLTP 场景的默认切了过去）在写语句执行时先上锁，把冲突处理挪进写路径——等待与 <a href="/cs/distributed-deadlock">分布式死锁</a> 那课的跨节点等待图随之而来，锁持有变长，换来的是重试率下降。</p><p><span class="marginnote">固定税目：一次提交至少两次 TSO 往返（startTS 与 commitTS），加上每个键锁、数据、写记录的多次 KV 写。Percolator 论文自述这套延迟只配增量作业——TiDB 的全部工程化，都是在给这句话翻案。</span></p><p><span class="marginnote">「乐观／悲观」的名字说的是对冲突的预期：乐观模式赌冲突罕见，先干活后对账，撞车了整单重来；悲观模式赌冲突频繁，先占坑再干活。选错脾气的代价很直观——热点行上跑乐观事务，重试率会随并发往上翻着涨，这正是 TiDB 把 OLTP 默认切成悲观模式的原因。</span></p>',9)),(r(),o(l,null,{default:t(()=>[i(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E5%86%99%E4%BA%8B%E5%8A%A1%EF%BC%9A%E6%94%B9%E4%B8%A4%E4%B8%AA%E4%BA%92%E7%9B%B8%E5%86%B2%E7%AA%81%E7%9A%84%E9%94%AE%22%5D%20--%3E%20OPT%5B%22%E4%B9%90%E8%A7%82%E6%A8%A1%E5%BC%8F%EF%BC%9A%E5%85%88%E6%89%A7%E8%A1%8C%EF%BC%8C%E6%8F%90%E4%BA%A4%E6%97%B6%E6%89%8D%E8%A7%81%E5%86%B2%E7%AA%81%22%5D%0A%20%20TX%20--%3E%20PES%5B%22%E6%82%B2%E8%A7%82%E6%A8%A1%E5%BC%8F%EF%BC%9A%E5%86%99%E8%AF%AD%E5%8F%A5%E6%89%A7%E8%A1%8C%E6%97%B6%E5%85%88%E4%B8%8A%E9%94%81%22%5D%0A%20%20OPT%20--%3E%20OC%5B%22%E5%86%B2%E7%AA%81%E5%B0%91%EF%BC%9A%E5%85%A8%E7%A8%8B%E6%97%A0%E9%94%81%E7%AD%89%E5%BE%85%EF%BC%8C%E5%90%9E%E5%90%90%E9%AB%98%22%5D%0A%20%20OC%20--%3E%20OF%5B%22%E5%86%B2%E7%AA%81%E5%A4%9A%EF%BC%9A%E6%8F%90%E4%BA%A4%E6%97%B6%E6%92%9E%E8%BD%A6%EF%BC%8C%E6%95%B4%E5%8D%95%E9%87%8D%E8%AF%95%22%5D%0A%20%20PES%20--%3E%20PC%5B%22%E9%94%81%E5%85%88%E5%88%B0%E6%89%8B%EF%BC%8C%E5%86%B2%E7%AA%81%E6%96%B9%E5%8E%9F%E5%9C%B0%E7%AD%89%E5%BE%85%22%5D%0A%20%20PC%20--%3E%20PF%5B%22%E9%94%81%E6%8C%81%E6%9C%89%E5%8F%98%E9%95%BF%EF%BC%8C%E6%8D%A2%E6%9D%A5%E9%87%8D%E8%AF%95%E7%8E%87%E4%B8%8B%E9%99%8D%E4%B8%8E%E6%AD%BB%E9%94%81%E6%A3%80%E6%B5%8B%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"为什么主锁落定即全局提交：任何读者读到数据都要沿 write 列回溯版本，而 write 记录只有在锁清掉之后才可见；主锁行的 write 记录是唯一真相源，次键的清理因此可以乱序、异步、无限重试——「补写一条 write 记录」这个动作幂等，做多少遍结果一样。Async commit 与 1PC 这类优化砍的是轮次：小事务的所有键一次写完，或让提交戳由主锁所在 Raft 组的日志序近似给出，省掉与 TSO 的第二次往返；代价是恢复协议更复杂，崩溃时要知道「这个事务曾打算用什么戳」。工程边界也在这里：单事务键数太多时，次锁清理变成清理风暴；超长事务把读者的退避拖成雪崩。Percolator 系协议的失败模式几乎都落在这两处。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"前滚／回滚可以类比接手一个弃工的现场：主锁行的 write 记录相当于「竣工验收单」，有单说明活干完了，接手者只需替各分项补齐验收单（补 write 记录）；没单就拆掉残锁重新来。补单做多少遍结果都一样——这就是幂等，也是清理可以无限重试的底气。")],-1)),(r(),o(l,null,{default:t(()=>[i(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUF%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E7%BC%93%E5%86%B2%E5%86%99%E9%9B%86%22%5D%20--%3E%20PRI%5B%22%E9%80%89%E4%B8%BB%E9%94%AE%EF%BC%8C%E5%86%99%E4%B8%BB%E9%94%81%22%5D%0A%20%20PRI%20--%3E%20SEC%5B%22%E5%85%B6%E4%BD%99%E9%94%AE%E5%86%99%E6%AC%A1%E9%94%81%EF%BC%8C%E6%8C%87%E5%90%91%E4%B8%BB%E9%94%AE%22%5D%0A%20%20SEC%20--%3E%20PC%5B%22%E4%B8%BB%E9%94%AE%E5%86%99%20write%20%E8%AE%B0%E5%BD%95%EF%BC%9A%E6%8F%90%E4%BA%A4%E7%82%B9%22%5D%0A%20%20PC%20--%3E%20SC%5B%22%E6%AC%A1%E9%94%AE%E5%BC%82%E6%AD%A5%E8%A1%A5%20write%20%E8%AE%B0%E5%BD%95%22%5D%0A%20%20CR%5B%22%E8%AF%BB%E8%80%85%E9%81%87%E5%88%B0%E6%AE%8B%E9%94%81%22%5D%20--%3E%20LP%5B%22%E9%A1%BA%E6%AC%A1%E9%94%81%E6%8C%87%E9%92%88%E6%9F%A5%E4%B8%BB%E9%94%AE%22%5D%0A%20%20LP%20--%3E%20FW%5B%22%E4%B8%BB%E9%94%AE%E5%B7%B2%E6%8F%90%E4%BA%A4%EF%BC%9A%E5%89%8D%E6%BB%9A%E8%A1%A5%E5%AE%8C%22%5D%0A%20%20LP%20--%3E%20RB%5B%22%E4%B8%BB%E9%94%AE%E6%97%A0%E9%94%81%EF%BC%9A%E5%88%A0%E9%94%81%E5%9B%9E%E6%BB%9A%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算 Raft 与 Region 的内部账（共识课与存储课负责），也不把 Percolator 路线说成唯一解——下一课的 Calvin 连锁表都不要。与 Spanner 一句话对照：Spanner 的锁挂在组长内存里，崩溃恢复走共识组；Percolator 的锁躺在数据行里，崩溃恢复靠读者顺手清理。前者恢复快、实现厚；后者实现薄、读路径多一跳查锁。</p><p><span class="marginnote">为什么长事务在这里格外危险，代个数：事务持锁 10 秒，期间每个想读这行的新读者都要退避重试；若每秒来 100 个读者，10 秒就是上千次无效重试，队列越压越厚——「退避拖成雪崩」就是这么成型的。所以 Percolator 系的运维纪律是：严控事务时长的上限。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Percolator 的 2PC 没有协调者进程：主锁即提交点，次锁指向主锁，状态全在数据里。</li><li>崩溃判定权交给「查主键」：已提交则前滚，无主锁则回滚，动作幂等。</li><li>TiDB 的改造在税目上：TSO 批量发号、悲观模式把冲突处理挪进写路径。</li><li>优化方向是砍轮次（async commit、1PC）；失败模式集中在长事务与清理风暴。</li><li>出处：Peng and Dabek, OSDI 2010；TiDB/TiKV 事务模型文档口径。</li></ul>',5))])}const f=s(c,[["render",C]]);export{h as __pageData,f as default};
